class Widget {};

// Factory function returning a unique pointer
std::unique_ptr<Widget> createWidget() {
    return std::make_unique<Widget>(); // Ownership is transferred to caller
}

void sink(std::unique_ptr<Widget> w) { /* takes ownership */ }

int main() {
    // pW1 has exclusive ownership of the new Widget
    auto pW1 = createWidget();

    // sink(pW1); // Error: cannot copy a unique_ptr
    sink(std::move(pW1)); // OK: ownership is explicitly transferred to sink

    // After the move, pW1 is null and no longer owns the Widget
    assert(pW1 == nullptr);

    auto pW2 = createWidget();
    std::unique_ptr<Widget> pW3 = std::move(pW2); // Ownership transferred to pW3

    // pW3 goes out of scope here, and the Widget is automatically deleted.
    return 0;
}
